const required = [
  'RELIABILITY_N8N_BASE_URL',
  'RELIABILITY_N8N_API_KEY',
  'RELIABILITY_STALE_AFTER_MINUTES',
  'RELIABILITY_MONITORED_WORKFLOW_IDS',
  'RELIABILITY_ALERT_WEBHOOK_URL',
];
const missing = required.filter((key) => !$vars[key]);

if (missing.length) {
  throw new Error(`Set n8n variables before activating Heartbeat Monitor: ${missing.join(', ')}`);
}

return [{ json: { checkedAt: new Date().toISOString() } }];

const response = $input.first().json;
const executions = response.data ?? [];
const monitoredIds = String($vars.RELIABILITY_MONITORED_WORKFLOW_IDS)
  .split(',')
  .map((id) => id.trim())
  .filter(Boolean);
const staleAfterMinutes = Number($vars.RELIABILITY_STALE_AFTER_MINUTES);
const cutoff = Date.now() - staleAfterMinutes * 60 * 1000;

const stale = monitoredIds.flatMap((workflowId) => {
  const latest = executions
    .filter((item) => String(item.workflowId) === workflowId)
    .map((item) => ({ ...item, completedAt: new Date(item.stoppedAt ?? item.startedAt ?? 0).getTime() }))
    .sort((a, b) => b.completedAt - a.completedAt)[0];

  if (!latest || latest.completedAt < cutoff) {
    return [{
      workflowId,
      lastSuccessfulExecutionId: latest?.id ?? null,
      lastSuccessfulAt: latest?.stoppedAt ?? latest?.startedAt ?? null,
    }];
  }

  return [];
});

if (stale.length === 0) {
  return [];
}

return [{
  json: {
    event: 'n8n.workflow.heartbeat_stale',
    severity: 'warning',
    detectedAt: new Date().toISOString(),
    staleAfterMinutes,
    staleWorkflows: stale,
    runbook: 'Confirm whether each workflow was expected to run, then inspect its last execution before enabling retries.',
  },
}];
